public struct Branch {
    public var name: String
    public var lastCommitSha: String
    public var protected: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(name: String, lastCommitSha: String, protected: Bool) {
        self.name = name
        self.lastCommitSha = lastCommitSha
        self.protected = protected
    }
}



extension Branch: Equatable, Hashable {
    public static func ==(lhs: Branch, rhs: Branch) -> Bool {
        if lhs.name != rhs.name {
            return false
        }
        if lhs.lastCommitSha != rhs.lastCommitSha {
            return false
        }
        if lhs.protected != rhs.protected {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(name)
        hasher.combine(lastCommitSha)
        hasher.combine(protected)
    }
}


