public enum DeviceLoginStatus {
    
    case pending
    case slowDown
    case expired
    case denied
    case authorized(token: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeDeviceLoginStatus: FfiConverterRustBuffer {
    typealias SwiftType = DeviceLoginStatus

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DeviceLoginStatus {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .pending
        
        case 2: return .slowDown
        
        case 3: return .expired
        
        case 4: return .denied
        
        case 5: return .authorized(token: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: DeviceLoginStatus, into buf: inout [UInt8]) {
        switch value {
        
        
        case .pending:
            writeInt(&buf, Int32(1))
        
        
        case .slowDown:
            writeInt(&buf, Int32(2))
        
        
        case .expired:
            writeInt(&buf, Int32(3))
        
        
        case .denied:
            writeInt(&buf, Int32(4))
        
        
        case let .authorized(token):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(token, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
