public enum OctoError {

    
    
    case Auth(msg: String
    )
    case NotFound(msg: String
    )
    case Api(msg: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeOctoError: FfiConverterRustBuffer {
    typealias SwiftType = OctoError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> OctoError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Auth(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 2: return .NotFound(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Api(
            msg: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: OctoError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Auth(msg):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(msg, into: &buf)
            
        
